import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class E {

	static long MOD=998244353;
	static long[] factorials, invFactorials;

	public static void main(String[] args) {
		precompute();
		MyScanner sc=new MyScanner();
		try {
		int totalN=sc.nextInt(), totalK=sc.nextInt();
		if (totalK==0) {
			System.out.println(factorials[totalN]);
			return;
		}
		if (totalK>=totalN) {
			System.out.println(0);
			return;
		}
		int remaining=totalN-totalK;
		long assignWays=calculatePower(remaining, totalN);
		long pickWays=computeCombination(totalN, remaining);
		long totalWays=product(assignWays, pickWays);
		System.out.println(product(totalWays, 2));
		}
		catch(Throwable t) {
			System.out.println(0);
		}
	}

	static long calculatePower(int base, long exponent) {
		long total=0;
		for (int i=0; i<base; i++) {
			long term=fastExponentiation(base-i, exponent)*computeCombination(base, i);
			if (i%2==0) {
				total=add(total, term);
			} else {
				total=subtract(total, term);
			}
		}
		return total;
	}

	static void precompute() {
		factorials=new long[1_000_000];
		invFactorials=new long[1_000_000];
		factorials[0]=invFactorials[0]=1;
		for (int i=1; i<factorials.length; i++) factorials[i]=multiply(factorials[i-1], i);
		invFactorials[factorials.length-1]=fastPow(factorials[factorials.length-1], MOD-2);
		for (int i=invFactorials.length-2; i>=0; i--) invFactorials[i]=multiply(invFactorials[i+1], i+1);
	}

	static long computeCombination(int n, int k) {
		return multiply(factorials[n], multiply(invFactorials[k], invFactorials[n-k]));
	}

	static long add(long a, long b) {
		return (a+b)%MOD;
	}

	static long subtract(long a, long b) {
		return ((a-b)%MOD+MOD)%MOD;
	}

	static long multiply(long a, long b) {
		return a*b%MOD;
	}

	static long fastExponentiation(long base, long exp) {
		if (exp==0) return 1;
		long half=fastExponentiation(base, exp/2);
		if (exp%2==0) return multiply(half, half);
		return multiply(half, multiply(half, base));
	}

	static class MyScanner {
		BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st=new StringTokenizer("");

		public String next() {
			while (!st.hasMoreElements())
				try {
					st=new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}
	}
}
